    var steps: [GuidedStep] {
        let maternityCouplePoses: Set<GuidedPose> = [
            .maternityHusbandEmbrace, .maternityHusbandWalk, .maternityHusbandFaceToFace
        ]
        let newbornPoses = Set(GuidedPose.allCases.filter { $0.package == .newborn })
        return cues.map {
            let recipient: String? = if package == .couples || package == .weddingEngagement || maternityCouplePoses.contains(self) {
                "Couple"
            } else if package == .friendsGroups {
                "Group"
            } else if package == .family {
                "Family"
            } else if newbornPoses.contains(self) {
                "Caregiver"
            } else if self == .kidsSiblingSideHug {
                "Children"
            } else if package == .kids {
                "Child"
            } else {
                nil
            }
            return GuidedStep(
                instruction: $0,
                action: .subjectPose,
                recipientOverride: recipient
            )
        }
    }

    var conflicts: Set<String> {
        var result: Set<String> = ["body_too_square", "body_too_profile", "arms_flat_against_body", "arm_hidden"]
        if self == .overShoulder || self == .lookAwayMasculine || self == .graduationOverShoulder || self == .maternitySideProfile || self == .kidsPeekAround || self == .weddingProposalReaction {
            result.formUnion(["face_missing", "face_too_profile", "face_turned_away"])
        }
        if category == .moving { result.insert("camera_unstable") }
        if category == .seated { result.insert("feet_cropped") }
        return result
    }
}

enum GuidedCameraPosition: String, CaseIterable, Identifiable {
    case eyeLevel = "C1", chestLevel = "C2", waistLevel = "C3", elevated = "C4", side = "C5"
    var id: String { rawValue }
    var title: String {
        switch self {
        case .eyeLevel: return "Eye level"
        case .chestLevel: return "Chest level"
        case .waistLevel: return "Waist level, farther back"
        case .elevated: return "Slightly above eye level"
        case .side: return "To the side, at eye level"
        }
    }
    func steps(moveRight: Bool) -> [GuidedStep] {
        switch self {
        case .eyeLevel:
            return [GuidedStep(instruction: "Hold the camera at their eye level.", action: .cameraHeight)]
        case .chestLevel:
            return [GuidedStep(instruction: "Lower the camera to their chest level.", action: .cameraHeight)]
        case .waistLevel:
            return [GuidedStep(instruction: "Lower the camera to their waist level.", action: .cameraHeight),
                    GuidedStep(instruction: "Step back until their feet fit.", action: .photographerMove)]
        case .elevated:
            return [GuidedStep(instruction: "Raise the camera just above their eye level.", action: .cameraHeight),
                    GuidedStep(instruction: "Angle the camera down slightly.", action: .cameraPitch)]
        case .side:
            return [GuidedStep(instruction: "Hold the camera at their eye level.", action: .cameraHeight),
                    GuidedStep(instruction: moveRight ? "Move a little to your right around the subject." : "Move a little to your left around the subject.", action: .photographerMove)]
        }
    }
}

struct Advice: Equatable {
    let type: String
    let recipient: String
    let instruction: String
    let tone: AdviceTone

    var visualGuidanceDirection: VisualGuidanceDirection? {
        let instruction = instruction.lowercased()

        if instruction.contains("move") && instruction.contains("left") { return .left }
        if instruction.contains("move") && instruction.contains("right") { return .right }
        if instruction.contains("raise") || instruction.contains("move up") { return .up }
        if instruction.contains("lower") || instruction.contains("move down") { return .down }
        if instruction.contains("step closer") || instruction.contains("move closer") { return .closer }
        if instruction.contains("step back") || instruction.contains("farther back") || instruction.contains("move back") {
            return .farther
        }
        if instruction.contains("tilt left") { return .rotateLeft }
        if instruction.contains("tilt right") { return .rotateRight }
        if type == "feet_cropped" { return .farther }
        return nil
    }

    var directionSymbol: String? {
        if let visualGuidanceDirection { return visualGuidanceDirection.symbol }
        switch type {
        case "camera_tilted", "horizon_tilted": return "arrow.triangle.2.circlepath.camera"
        case "headroom_too_large", "headroom_too_small": return "arrow.up.and.down"
        case "limb_cropped": return "figure.walk"
        case "subject_too_close", "subject_too_far", "scene_excluded", "feet_cropped": return "arrow.up.left.and.arrow.down.right"
        default: return recipient == "Subject" ? "figure.stand" : nil
        }
    }
}

enum VisualGuidanceDirection: String, Equatable {
    case left
    case right
    case up
    case down
    case closer
    case farther
    case rotateLeft
    case rotateRight

    var symbol: String {
        switch self {
        case .left: return "arrow.left"
        case .right: return "arrow.right"
        case .up: return "arrow.up"
        case .down: return "arrow.down"
        case .closer: return "arrow.down.right.and.arrow.up.left"
        case .farther: return "arrow.up.left.and.arrow.down.right"
        case .rotateLeft: return "rotate.left"
        case .rotateRight: return "rotate.right"
        }
    }

    var movementOffset: CGSize {
        switch self {
        case .left: return CGSize(width: -14, height: 0)
        case .right: return CGSize(width: 14, height: 0)
        case .up: return CGSize(width: 0, height: -14)
        case .down: return CGSize(width: 0, height: 14)
        case .closer: return CGSize(width: 0, height: -8)
        case .farther: return CGSize(width: 0, height: 8)
        case .rotateLeft, .rotateRight: return .zero
        }
    }
}

